-- Демо-данные: дисциплины и пара долгов студента для локальной разработки.
--
-- Продолжение цепочки dev-сидов. Зависит от 00002_seed_dev_teacher_student
-- (teacher@ / student@) — goose накатывает файлы по порядку, поэтому здесь
-- эти аккаунты уже существуют.
--
-- На чистой БД без эмулятора нет ни дисциплин, ни долгов, и кабинет
-- студента пустой. Этот сид наполняет его минимальным реалистичным
-- набором: 2 дисциплины, привязки преподавателя и студента к ним и 2
-- открытых долга у студента.
--
-- Состав:
--   2 дисциплины (MATH-101, PROG-201), ведёт teacher@academic.local
--   student@academic.local учится на обеих
--   2 открытых долга студента по этим дисциплинам (выставил teacher@)
--
-- ID детерминированные — ON CONFLICT (id) DO NOTHING делает накат идемпотентным.

-- +goose Up
-- +goose StatementBegin

-- Дисциплины (created_by — служебный системный user из 00010_seed_rbac).
ON CONFLICT (id) DO NOTHING;

-- Преподаватель ведёт обе дисциплины (нужно для «должников по моим дисциплинам»).
ON CONFLICT (id) DO NOTHING;

-- Студент учится на обеих дисциплинах.
ON CONFLICT (id) DO NOTHING;

-- Пара открытых долгов студента (выставил teacher@). status='open' ⇒
-- final_grade/graded_at/graded_by остаются NULL (constraint debts_grade_consistency).
ON CONFLICT (id) DO NOTHING;

-- ── Расширенный демо-набор ──────────────────────────────────────────────────
-- Ещё 2 дисциплины (ведёт teacher2@ = cccc…-0002), запись остальных
-- студентов на дисциплины и ~30 долгов с разными статусами.

ON CONFLICT (id) DO NOTHING;

-- teacher@ ведёт MATH-101 и PROG-201 (выше), teacher2@ ведёт DB-301 и OS-202.
ON CONFLICT (id) DO NOTHING;

-- Запись студентов 02..15 на дисциплины (каждый на 2 дисциплины).
-- Чередуем пары (MATH+PROG) и (DB+OS), чтобы у разных групп были разные
-- предметы. student_disciplines уникальна по (student_id, discipline_id).
ON CONFLICT (id) DO NOTHING;

-- Долги. Большинство open; несколько graded (с final_grade/graded_at/graded_by,
-- иначе нарушится debts_grade_consistency) и пара cancelled. По одной паре
-- (student, discipline) — максимум один open (idx_debts_unique_open).
-- Долги по MATH-101/PROG-201 выставил teacher@ (…-0001), по DB-301/OS-202 — teacher2@ (…-0002).
ON CONFLICT (id) DO NOTHING;

-- +goose StatementEnd

-- +goose Down
-- +goose StatementBegin
-- Удаляем в обратном порядке зависимостей (debts → привязки → disciplines).
-- Префиксы детерминированных ID позволяют снести весь демо-набор разом.
DELETE FROM debts               WHERE id::text LIKE '00deb700-%';
DELETE FROM student_disciplines WHERE id::text LIKE '00d15c02-%';
DELETE FROM teacher_disciplines WHERE id::text LIKE '00d15c01-%';
DELETE FROM disciplines         WHERE id::text LIKE '00d15c00-%';
-- +goose StatementEnd
